export function newGame(archetype='visionario',difficulty='normal',legacy={}){const a=archetypes.find(a=>a.id===archetype)||archetypes[0];return {version:1,archetype:a.id,difficulty,turn:1,actions:0,money:10+(a.money||0)+(legacy.foundation||0),income:1,chaos:0,politics:a.politics||0,media:a.media||0,tech:a.tech||0,exposure:(a.exposure||0)+(difficulty==='investigado'?30:0),regions:regions.map((r,i)=>({...r,stability:85,control:a.id==='oligarca'&&i<2?30:0})),selected:1,history:[{title:'O tabuleiro está pronto.',text:'Escolha uma região, execute operações e avance o trimestre.',type:'neutral'}],status:'playing',used:[],seed:Math.floor(Math.random()*1e9),rewarded:false};}
export function random(s){s.seed=(Math.imul(1664525,s.seed)+1013904223)>>>0;return s.seed/4294967296;}
export function blocked(s,o){if(s.status!=='playing')return 'Partida encerrada';if(s.difficulty!=='magnata'&&s.actions>=3)return 'Sem ações neste trimestre';if(s.money<o.cost)return 'Patrimônio insuficiente';for(const[k,v]of Object.entries(o.requires))if(s[k]<v)return `Requer ${v}% de ${labels[k]}`;return '';}
export const labels={money:'patrimônio',income:'receita/trimestre',chaos:'caos',politics:'influência',media:'mídia',tech:'tecnologia',exposure:'exposição'};
function clamp(s){for(const k of ['chaos','politics','media','tech'])s[k]=Math.max(0,Math.min(100,s[k]));s.exposure=Math.max(-30,Math.min(100,s.exposure));s.money=Math.round(s.money*100)/100;}
export function outcome(s){clamp(s);if(s.exposure>=100||s.money<=0){s.status='lost';s.ending=s.money<=0?'Seu império entrou em falência.':'Você foi exposto. O mundo conhece seu nome.';}else if(s.chaos>=100){s.status='won';s.ending=s.used.includes('nuclear')?'Guerra nuclear':s.used.includes('pathogen')?'Pandemia global':s.tech>=75?'Distopia tecnológica':s.politics>=70?'Implosão política':'Colapso econômico';}return s.status;}
export function execute(s,id){const o=operations.find(o=>o.id===id);if(!o||blocked(s,o))return false;s.money-=o.cost;s.actions++;let effect={...o.effect},note='';if(id==='short'&&random(s)<.35){effect={exposure:3};note=' A aposta falhou.';}if(id==='journalist'&&random(s)<.3){effect={exposure:15};note=' Efeito Streisand: a denúncia ganhou força.';}for(const[k,v]of Object.entries(effect))s[k]+=k==='tech'&&s.archetype==='visionario'?Math.round(v*1.2):v;const r=s.regions[s.selected];r.stability=Math.max(0,r.stability-(effect.chaos||0)*1.8);r.control=Math.min(100,r.control+(effect.politics||0)*(r.corruption/100+.5));s.used.push(id);s.history.unshift({title:o.name,text:`${r.name}.${note} ${describe(effect)}`,type:effect.exposure>10?'danger':'positive'});outcome(s);return true;}
export function describe(effect){return Object.entries(effect).map(([k,v])=>`${v>0?'+':''}${Number.isInteger(v)?v:v.toFixed(1)}${k==='money'||k==='income'?'B':'%'} ${labels[k]}`).join(' · ');}
const events=[['Documentos vazados','Uma fonte anônima entrega arquivos à imprensa.',{exposure:14}],['Crise financeira','Seus ativos perdem valor com a turbulência.',{money:-1.8,chaos:4}],['Parceria inesperada','Um investidor decide apostar no seu império.',{money:2}],['Eleição surpresa','Seus aliados perderam espaço no governo.',{politics:-8}],['Investigação internacional','Seus negócios estão sob análise.',{exposure:10}],['Mercados em alta','Suas participações renderam acima do esperado.',{money:1.5}],['Protestos nas ruas','A tensão social toma conta das capitais.',{chaos:5}],['Uma nova pauta','A imprensa volta os olhos para outro escândalo.',{exposure:-9}]];
export function endTurn(s){if(s.status!=='playing')return false;s.turn++;s.actions=0;const revenue=s.income*(1+s.regions[s.selected].gdp/250);s.money+=revenue;s.exposure-=2+s.media*.07;const count=1+Math.floor(random(s)*3);s.history.unshift({title:`Trimestre ${s.turn} · resultados`,text:`+$${revenue.toFixed(1)}B em receita. Sua mídia reduziu a exposição.`,type:'positive'});for(let i=0;i<count;i++){const [title,text,effect]=events[Math.floor(random(s)*events.length)];for(const[k,v]of Object.entries(effect))s[k]+=v;s.history.unshift({title,text:`${text} ${describe(effect)}`,type:effect.exposure>0?'danger':'neutral'});}s.history=s.history.slice(0,45);outcome(s);return true;}
